Matching Ayahs
- = Alif, Lam, Mim. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Essi sono sulla retta via del loro Signore, e sono quelli che avranno successo. 2:5; 31:5
- = O figli di Israele, ricordatevi del Mio favore che vi ho concesso e che vi ho preferito a tutti i popoli (del mondo). 2:47; 2:122
- = Questa è una comunità che è passata. Avrà ciò che si è guadagnata, e voi avrete ciò che vi siete guadagnati. E non sarete interrogati su ciò che facevano. 2:134; 2:141
- = Vi rimarranno in eterno; non sarà loro alleggerito il castigo e non sarà loro concessa tregua. 2:162; 3:88
- = Eccetto coloro che, dopo di ciò, si pentono e si correggono. In verità, Allah è Perdonatore, Misericordioso. 3:89; 24:5
- = Quanto a coloro che sono miscredenti e smentiscono i Nostri segni – essi sono i compagni del Fuoco. 5:10; 5:86
- = E non giunge loro alcun segno tra i segni del loro Signore, senza che se ne allontanino. 6:4; 36:46
- = E già furono derisi dei messaggeri prima di te, ma coloro che li deridevano furono circondati da ciò di cui si facevano beffe. 6:10; 21:41
- = Di': "Io temo, se disobbedisco al mio Signore, il castigo di un Giorno terribile." 6:15; 39:13
- = Allora il terremoto li colpì, e rimasero cadaveri nelle loro case. 7:78; 7:91
- = Allora gettò il suo bastone, ed ecco che divenne un serpente evidente. 7:107; 26:32
- = Ed estrasse la sua mano, ed ecco che divenne bianca (splendente) per coloro che guardavano. 7:108; 26:33
- = Dissero: "Abbiamo creduto nel Signore dei mondi." 7:121; 26:47
- = Il Signore di Mosè e di Aronne. 7:122; 26:48
- = E darò loro tempo. In verità, il Mio piano è fermo. 7:183; 68:45
- = Egli è Colui che ha inviato il Suo Messaggero con la guida e la religione della verità, per renderla trionfante su ogni religione, anche se ciò dispiace ai politeisti. 9:33; 61:9
- = O Profeta, combatti i miscredenti e gli ipocriti e sii severo con loro. Il loro rifugio sarà l'Inferno, e qual triste destino! 9:73; 66:9
- = E dicono: "Quando si realizzerà questa promessa, se siete veridici?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = E inviammo Mosè con i Nostri segni e con un'autorità evidente. 11:96; 40:23
- = E demmo a Mosè la Scrittura, ma ne nacque controversia. E se non fosse stata una parola già emanata dal tuo Signore, sarebbe stato deciso tra loro. E sono in proposito in dubbio profondo. 11:110; 41:45
- = Ciò non è affatto difficile per Allah. 14:20; 35:17
- = "Quando l'avrò plasmato e vi avrò insufflato del Mio Spirito, prosternatevi dinanzi a lui." 15:29; 38:72
- = Allora gli angeli si prostrarono tutti insieme. 15:30; 38:73
- = (Allah) disse: "Allora esci da esso, perché sei maledetto." 15:34; 38:77
- = (Iblīs) disse: "Signore mio, concedimi allora una tregua fino al Giorno in cui saranno risuscitati." 15:36; 38:79
